<template><view class="page"><text class="eyebrow">从一个方向开始</text><text class="title">设置我的健康计划</text><text class="hint">之后随时可以调整，不需要一次决定全部。</text><view class="cards"><button :class="['choice',{selected:kind==='weight'}]" @tap="kind='weight'"><image src="/static/illustrations/program-weight.png" mode="aspectFill"/><view><text>体重管理</text><text>从规律记录与小行动开始</text></view></button><button :class="['choice',{selected:kind==='sleep'}]" @tap="kind='sleep'"><image src="/static/illustrations/program-sleep.png" mode="aspectFill"/><view><text>睡眠与精力</text><text>先找回更稳定的作息</text></view></button></view><view v-if="kind==='weight'" class="panel"><text class="label">目标方向</text><view class="directions"><button v-for="item in directions" :key="item.value" :class="{selected:direction===item.value}" @tap="direction=item.value">{{item.label}}</button></view><text class="label">目标体重（选填）</text><view class="input-row"><input v-model="targetWeightKg" type="digit" placeholder="例如 58"/><text>kg</text></view></view><text v-if="error" class="error">{{error}}</text><button class="submit" :loading="saving" @tap="save">开始我的计划</button></view></template>
<script setup lang="ts">import {ref} from 'vue';import type {PlanKind,WeightDirection} from '../../../../../packages/contracts/src/health-loop.js';import {healthLoopState} from '../../features/health-loop/health-loop.store.js';const kind=ref<PlanKind>('weight');const direction=ref<WeightDirection>('lose');const targetWeightKg=ref('');const saving=ref(false);const error=ref('');const directions:Array<{value:WeightDirection;label:string}>=[{value:'lose',label:'减重'},{value:'maintain',label:'保持'},{value:'gain',label:'增重'}];async function save(){error.value='';saving.value=true;try{const date=localDate();await healthLoopState.savePlan({kind:kind.value,direction:kind.value==='weight'?direction.value:undefined,targetWeightKg:kind.value==='weight'&&targetWeightKg.value?Number(targetWeightKg.value):undefined,startDate:date},date);uni.switchTab({url:'/pages/plan/PlanPage'});}catch(e){error.value=e instanceof Error?e.message:'暂时无法保存计划';}finally{saving.value=false;}}function localDate(){const n=new Date();return new Date(n.getTime()-n.getTimezoneOffset()*60000).toISOString().slice(0,10);}</script>
<style scoped>.page{min-height:100vh;box-sizing:border-box;padding:48rpx 32rpx;background:#f7fbf8;color:#1d3d2a}.eyebrow,.title,.hint,.label{display:block}.eyebrow{color:#649078;font-size:23rpx;font-weight:700}.title{margin-top:10rpx;font-size:46rpx;font-weight:700}.hint{margin-top:12rpx;color:#718b7a;font-size:24rpx;line-height:1.55}.cards{display:flex;flex-direction:column;gap:16rpx;margin-top:30rpx}.choice{display:flex;align-items:center;gap:20rpx;overflow:hidden;padding:0;border:2rpx solid #dceadc;border-radius:18rpx;text-align:left;background:#fff}.choice image{width:136rpx;height:136rpx}.choice text{display:block;color:#2e543d;font-size:29rpx;font-weight:700}.choice text:last-child{margin-top:8rpx;color:#708a7a;font-size:22rpx;font-weight:400}.selected{border-color:#70a77d;background:#f0f8ef}.panel{margin-top:24rpx;padding:24rpx;border:2rpx solid #dceadd;border-radius:18rpx;background:#fff}.label{margin-bottom:14rpx;color:#506e5a;font-size:25rpx}.directions{display:flex;gap:12rpx;margin-bottom:25rpx}.directions button{flex:1;padding:18rpx 8rpx;border:2rpx solid #dce9dd;border-radius:13rpx;color:#547361;background:#fff;font-size:25rpx}.directions .selected{border-color:#70a77d;color:#276c48;background:#e9f5ea}.input-row{display:flex;align-items:center;height:82rpx;border:2rpx solid #dce9dd;border-radius:14rpx}.input-row input{flex:1;height:100%;padding:0 20rpx;border:0;font-size:27rpx}.input-row text{padding-right:20rpx;color:#718b7a}.error{display:block;margin-top:18rpx;color:#b95d43;font-size:23rpx}.submit{width:100%;height:86rpx;margin-top:28rpx;border-radius:15rpx;color:#fff;background:#40865a;font-size:29rpx;line-height:86rpx}</style>
